# Synthetic login log for two 10-minute windows: (username, outcome)
# outcome: "ok", "bad_pw" (real user, wrong password), "no_user" (unknown)
normal = ["ok"] * 940 + ["bad_pw"] * 55 + ["no_user"] * 5
attack = normal + ["ok"] * 12 + ["bad_pw"] * 2900 + ["no_user"] * 6100

def window_stats(outcomes):
    n = len(outcomes)
    return {
        "attempts": n,
        "success_rate": round(outcomes.count("ok") / n, 3),
        "unknown_user_rate": round(outcomes.count("no_user") / n, 3),
    }

print("normal:", window_stats(normal))
print("attack:", window_stats(attack))
# output:
