from collections import defaultdict

USERS = {  # synthetic phone -> profile
    "+15550001": {"name": "Ana", "id": 1, "findable_by_phone": True},
    "+15550002": {"name": "Ben", "id": 2, "findable_by_phone": False},
}

# VULNERABLE: any caller can upload any number of phone numbers and
# gets a name and id back for every match: a phone-to-person oracle.
def match_contacts_bad(caller, phones):
    return {p: USERS[p] for p in phones if p in USERS}

DAILY_CAP = 500                      # far above a real address book upload
uploaded = defaultdict(int)          # caller -> numbers checked today

def match_contacts(caller, phones):
    uploaded[caller] += len(phones)
    if uploaded[caller] > DAILY_CAP:
        raise PermissionError("contact upload limit")   # log + review
    out = {}
    for p in phones:
        u = USERS.get(p)
        if u and u["findable_by_phone"]:   # respect the user's setting
            out[p] = {"id": u["id"]}       # minimal: a friend suggestion
    return out

print(match_contacts_bad("bot", ["+15550001", "+15550002"]))
print(match_contacts("bot", ["+15550001", "+15550002"]))
try:
    match_contacts("bot", [f"+1555{n:07d}" for n in range(1000)])
except PermissionError as e:
    print("blocked:", e)
