from collections import defaultdict

# Synthetic accounts and the identifiers they used
accounts = {
    "u1": {"dev-A", "card-1"},          "u2": {"dev-A", "card-2"},
    "u3": {"card-2", "addr-7"},         "u4": {"addr-7", "dev-B"},
    "u5": {"dev-C", "card-5"},          "u6": {"dev-D", "card-6"},
    "u7": {"dev-D", "ip-shared-cgnat"}, "u8": {"ip-shared-cgnat", "dev-E"},
}
WEAK = {"ip-shared-cgnat"}   # shared by thousands of honest users: no link

parent = {a: a for a in accounts}
def find(a):
    while parent[a] != a:
        parent[a] = parent[parent[a]]   # path halving
        a = parent[a]
    return a
def union(a, b):
    parent[find(a)] = find(b)

owner = {}                               # identifier -> first account seen
for acct, ids in accounts.items():
    for i in ids - WEAK:
        if i in owner: union(acct, owner[i])
        else: owner[i] = acct

rings = defaultdict(list)
for a in accounts:
    rings[find(a)].append(a)
for members in rings.values():
    print(sorted(members), "REVIEW" if len(members) >= 3 else "")
# output:
