HOLD_DAYS = 120      # outlast the usual dispute window on the first payment

def referral_decision(referrer, referee, today):
    shared = referrer["ids"] & referee["ids"]
    if shared:
        return f"deny: self-referral, shares {sorted(shared)}"
    if referee["first_paid_order_day"] is None:
        return "pending: referee has not paid yet"
    if referee["disputed"]:
        return "deny: referee payment disputed"
    age = today - referee["first_paid_order_day"]
    if age < HOLD_DAYS:
        return f"pending: hold {HOLD_DAYS - age} more days"
    return "pay reward"

