import random
random.seed(7)

# Synthetic month: 100,000 orders, 0.5% fraud. Scores: fraud tends high.
orders = []
for _ in range(100_000):
    fraud = random.random() < 0.005
    score = random.betavariate(5, 2) if fraud else random.betavariate(1.2, 6)
    orders.append((score, fraud))

def metrics(threshold):
    tp = sum(1 for s, f in orders if s >= threshold and f)
    fp = sum(1 for s, f in orders if s >= threshold and not f)
    fn = sum(1 for s, f in orders if s < threshold and f)
    tn = len(orders) - tp - fp - fn
    return dict(tp=tp, fp=fp, fn=fn, tn=tn,
                precision=round(tp / (tp + fp), 3),
                recall=round(tp / (tp + fn), 3),
                good_users_blocked=round(fp / (fp + tn), 4))

for t in (0.5, 0.7, 0.85):
    print(t, metrics(t))
